  "application": "report-generation",
  "case_id": "case-nike-stock-market-analysis-en",
  "language": "en",
  "report": {
    "type": "financial-report",
    "audience": "investor",
    "tone": "analytical, data-forward, professional"
  },
  "brief": {
    "title": "Nike Inc. (NKE) Historical Stock Performance Analysis (2000–2026)",
    "one_liner": "A comprehensive analysis of Nike's stock price trends, volatility, and trading volume over a 26-year period to inform long-term investment perspectives.",
    "goal": "Provide investors with a clear understanding of Nike's historical stock performance, identify key growth phases and downturns, assess volatility patterns, and highlight long-term return characteristics to support informed investment decision-making."
  },
  "required_sections": [
    {
      "section_id": "executive-summary",
      "title": "Executive Summary",
      "objective": "Summarize the overall stock performance trajectory from 2000 to 2026, including cumulative returns and key milestones."
    },
    {
      "section_id": "price-trend-analysis",
      "title": "Long-Term Price Trend Analysis",
      "objective": "Analyze the closing price trend over the full time period, identifying major bull and bear phases, all-time highs and lows, and structural shifts in valuation."
    },
    {
      "section_id": "volatility-analysis",
      "title": "Volatility and Risk Assessment",
      "objective": "Examine daily price ranges (High–Low spread), rolling volatility measures, and periods of elevated risk such as market crises."
    },
