      "section_id": "volume-analysis",
      "title": "Trading Volume Patterns",
      "objective": "Analyze trading volume trends over time, identify periods of unusually high or low activity, and correlate volume spikes with price movements."
    },
    {
      "section_id": "annual-performance",
      "title": "Annual and Decade-Level Performance Breakdown",
      "objective": "Provide year-over-year and decade-level return summaries, highlighting the best and worst performing years and compounding growth rates."
    },
    {
      "section_id": "key-takeaways",
      "title": "Key Takeaways and Investment Implications",
      "objective": "Synthesize findings into actionable insights for long-term investors, including risk-return profile assessment and notable patterns."
    }
  ],
  "kpis": [
    {
      "name": "Cumulative Return",
      "description": "Total percentage return from the first trading day in 2000 to the most recent data point, based on closing prices."
    },
    {
      "name": "Compound Annual Growth Rate (CAGR)",
      "description": "Annualized growth rate of the closing price over the full dataset period."
    },
    {
      "name": "Maximum Drawdown",
      "description": "The largest peak-to-trough decline in closing price observed during the dataset period."
    },
    {
      "name": "Average Daily Trading Volume",
      "description": "Mean daily trading volume across the entire period, with comparison across different eras."
    },
    {
      "name": "Annualized Volatility",
      "description": "Standard deviation of daily returns annualized (×√252) as a measure of overall stock risk."
    }
  ],
  "analysis_dimensions": [
    "Date",
    "Close",
    "High",
    "Low",
    "Volume"
  ]
}

