import json

with open('/tmp/nike_chart_data.json', 'r') as f:
    data = json.load(f)

# Serialize for embedding
monthly_dates_js = json.dumps(data['monthly_dates'])
monthly_closes_js = json.dumps(data['monthly_closes'])
monthly_volumes_js = json.dumps(data['monthly_volumes'])
monthly_highs_js = json.dumps(data['monthly_highs'])
monthly_lows_js = json.dumps(data['monthly_lows'])
years_js = json.dumps(data['years'])
annual_returns_js = json.dumps(data['annual_returns'])
annual_avg_vols_js = json.dumps(data['annual_avg_vols'])
roll_dates_js = json.dumps(data['roll_dates'])
roll_vols_js = json.dumps(data['roll_vols'])
dd_dates_js = json.dumps(data['dd_dates'])
dd_vals_js = json.dumps(data['dd_vals'])

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Nike Inc. (NKE) — Historical Stock Performance Analysis 2000–2026</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {{
    --bg: #0f1117;
    --surface: #1a1d2e;
    --surface2: #212438;
    --border: #2e3250;
    --text: #e8eaf0;
    --text-muted: #8b90a8;
    --accent: #f57c00;
    --accent2: #1565c0;
    --green: #2e7d32;
    --red: #c62828;
    --green-light: #4caf50;
    --red-light: #ef5350;
    --font: 'Segoe UI', system-ui, -apple-system, sans-serif;
  }}
  * {{ box-sizing: border-box; margin: 0; padding: 0; }}
  body {{ background: var(--bg); color: var(--text); font-family: var(--font); line-height: 1.6; }}

  .header {{
    background: linear-gradient(135deg, #0d1b3e 0%, #1a0a2e 50%, #0d1b3e 100%);
    border-bottom: 2px solid var(--accent);
    padding: 48px 40px 36px;
  }}
  .header-inner {{ max-width: 1200px; margin: 0 auto; }}
  .ticker-badge {{
    display: inline-block; background: var(--accent); color: #fff;
    font-weight: 700; font-size: 13px; letter-spacing: 1.5px;
    padding: 4px 12px; border-radius: 4px; margin-bottom: 16px;
  }}
  h1 {{ font-size: 2.4rem; font-weight: 700; letter-spacing: -0.5px; margin-bottom: 8px; }}
  .subtitle {{ color: var(--text-muted); font-size: 1rem; }}
  .meta {{ margin-top: 16px; color: var(--text-muted); font-size: 0.85rem; }}

  .container {{ max-width: 1200px; margin: 0 auto; padding: 40px 40px; }}

  /* KPI Cards */
  .kpi-grid {{
    display: grid; grid-template-columns: repeat(5, 1fr); gap: 16px;
    margin-bottom: 48px;
  }}
  .kpi-card {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px 18px;
    transition: border-color 0.2s;
  }}
  .kpi-card:hover {{ border-color: var(--accent); }}
  .kpi-label {{
    font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1.2px;
    color: var(--text-muted); margin-bottom: 8px;
  }}
  .kpi-value {{
    font-size: 1.85rem; font-weight: 700; line-height: 1.1;
  }}
  .kpi-value.positive {{ color: var(--green-light); }}
  .kpi-value.negative {{ color: var(--red-light); }}
  .kpi-value.neutral {{ color: var(--accent); }}
  .kpi-sub {{ font-size: 0.78rem; color: var(--text-muted); margin-top: 4px; }}

  /* Section */
  .section {{ margin-bottom: 56px; }}
  .section-header {{
    display: flex; align-items: center; gap: 12px;
    margin-bottom: 24px; padding-bottom: 12px;
    border-bottom: 1px solid var(--border);
  }}
  .section-number {{
    background: var(--accent); color: #fff;
    width: 28px; height: 28px; border-radius: 6px;
    display: flex; align-items: center; justify-content: center;
    font-size: 0.8rem; font-weight: 700; flex-shrink: 0;
  }}
  h2 {{ font-size: 1.35rem; font-weight: 600; }}

  .section-intro {{
    color: var(--text-muted); font-size: 0.92rem;
    margin-bottom: 24px; max-width: 800px; line-height: 1.7;
  }}

  /* Charts */
  .chart-wrap {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 24px;
    margin-bottom: 20px;
  }}
  .chart-title {{
    font-size: 0.85rem; font-weight: 600; color: var(--text-muted);
    text-transform: uppercase; letter-spacing: 0.8px; margin-bottom: 16px;
  }}
  canvas {{ display: block; }}

  /* Phase table */
  .phase-grid {{
    display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px;
    margin-top: 20px;
  }}
  .phase-card {{
    background: var(--surface2);
    border: 1px solid var(--border);
    border-left: 3px solid;
    border-radius: 8px;
    padding: 16px;
  }}
  .phase-card.bull {{ border-left-color: var(--green-light); }}
  .phase-card.bear {{ border-left-color: var(--red-light); }}
  .phase-card.consolidation {{ border-left-color: #ffc107; }}
  .phase-period {{ font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; color: var(--text-muted); }}
  .phase-name {{ font-weight: 600; margin: 4px 0; }}
  .phase-return {{ font-size: 1.1rem; font-weight: 700; }}
  .phase-return.bull {{ color: var(--green-light); }}
  .phase-return.bear {{ color: var(--red-light); }}
  .phase-desc {{ font-size: 0.78rem; color: var(--text-muted); margin-top: 6px; }}

  /* Annual table */
  .annual-table {{
    width: 100%; border-collapse: collapse; font-size: 0.88rem;
    margin-top: 20px;
  }}
  .annual-table th {{
    background: var(--surface2); padding: 10px 14px;
    text-align: left; font-size: 0.72rem; text-transform: uppercase;
    letter-spacing: 0.8px; color: var(--text-muted);
    border-bottom: 1px solid var(--border);
  }}
  .annual-table td {{
    padding: 8px 14px; border-bottom: 1px solid var(--border);
  }}
  .annual-table tr:hover td {{ background: var(--surface2); }}
  .ret-positive {{ color: var(--green-light); font-weight: 600; }}
  .ret-negative {{ color: var(--red-light); font-weight: 600; }}
  .ret-bar {{
    display: inline-block; height: 8px; border-radius: 2px; vertical-align: middle; margin-left: 8px;
  }}

  /* Insights box */
  .insight-box {{
    background: var(--surface2);
    border: 1px solid var(--border);
    border-left: 4px solid var(--accent);
    border-radius: 8px;
    padding: 20px 24px;
    margin-top: 20px;
  }}
  .insight-box h3 {{ font-size: 0.85rem; text-transform: uppercase; letter-spacing: 0.8px; color: var(--accent); margin-bottom: 12px; }}
  .insight-list {{ list-style: none; }}
  .insight-list li {{
    padding: 6px 0; font-size: 0.9rem; color: var(--text-muted);
    padding-left: 16px; position: relative;
  }}
  .insight-list li::before {{ content: "›"; position: absolute; left: 0; color: var(--accent); font-weight: 700; }}

  /* Two column layout */
  .two-col {{ display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }}

  /* Footer */
  .footer {{
    background: var(--surface); border-top: 1px solid var(--border);
    padding: 24px 40px; text-align: center; color: var(--text-muted); font-size: 0.8rem;
  }}

  @media (max-width: 900px) {{
    .kpi-grid {{ grid-template-columns: repeat(2, 1fr); }}
    .phase-grid {{ grid-template-columns: 1fr; }}
    .two-col {{ grid-template-columns: 1fr; }}
  }}
</style>
</head>
<body>

<!-- HEADER -->
<header class="header">
  <div class="header-inner">
    <div class="ticker-badge">NYSE: NKE</div>
    <h1>Nike Inc. Historical Stock Performance</h1>
    <p class="subtitle">Comprehensive Analysis of 26 Years of Market Data &mdash; 2000 to 2026</p>
    <p class="meta">Report Date: January 2026 &nbsp;&bull;&nbsp; Data Period: January 3, 2000 &ndash; January 30, 2026 &nbsp;&bull;&nbsp; 6,559 Trading Days &nbsp;&bull;&nbsp; Audience: Long-Term Investors</p>
  </div>
</header>

<div class="container">

  <!-- EXECUTIVE SUMMARY -->
  <section class="section">
    <div class="section-header">
      <div class="section-number">1</div>
      <h2>Executive Summary</h2>
    </div>
    <p class="section-intro">
      Nike Inc. (NKE) delivered a cumulative return of <strong style="color:#e8eaf0">+1,282%</strong> over the 26-year period from January 2000 to January 2026, compounding at <strong style="color:#e8eaf0">10.6% annually</strong>. The stock's trajectory was far from linear: two decade-long bull markets punctuated by sharp drawdowns tied to macro events and company-specific challenges. After reaching an all-time high of $166.25 in November 2021, NKE entered a prolonged correction, ultimately declining over 62% from peak by January 2026. Despite this recent weakness, NKE's long-term compounding record remains a compelling case study in brand-driven growth and resilience.
    </p>

    <!-- KPI CARDS -->
    <div class="kpi-grid">
      <div class="kpi-card">
        <div class="kpi-label">Cumulative Return</div>
        <div class="kpi-value positive">+1,282%</div>
        <div class="kpi-sub">$4.47 &rarr; $61.81 per share</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">CAGR</div>
        <div class="kpi-value positive">10.60%</div>
        <div class="kpi-sub">Over 26.1 years</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Maximum Drawdown</div>
        <div class="kpi-value negative">&minus;68.5%</div>
        <div class="kpi-sub">Nov 2021 &rarr; Apr 2025</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Annualized Volatility</div>
        <div class="kpi-value neutral">31.2%</div>
        <div class="kpi-sub">Std dev of daily returns &times; &radic;252</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Avg Daily Volume</div>
        <div class="kpi-value neutral">10.7M</div>
        <div class="kpi-sub">Shares traded per day</div>
      </div>
    </div>

    <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:0">
      <div class="kpi-card" style="border-left:3px solid #4caf50">
        <div class="kpi-label">All-Time High</div>
        <div class="kpi-value" style="font-size:1.3rem;color:#4caf50">$166.25</div>
        <div class="kpi-sub">November 5, 2021</div>
      </div>
      <div class="kpi-card" style="border-left:3px solid #ef5350">
        <div class="kpi-label">All-Time Low (adj.)</div>
        <div class="kpi-value" style="font-size:1.3rem;color:#ef5350">$2.47</div>
        <div class="kpi-sub">February 25, 2000</div>
      </div>
      <div class="kpi-card" style="border-left:3px solid #f57c00">
        <div class="kpi-label">Current Price</div>
        <div class="kpi-value" style="font-size:1.3rem;color:#f57c00">$61.81</div>
        <div class="kpi-sub">January 30, 2026 (last data point)</div>
      </div>
    </div>
  </section>

  <!-- PRICE TREND ANALYSIS -->
  <section class="section">
    <div class="section-header">
      <div class="section-number">2</div>
      <h2>Long-Term Price Trend Analysis</h2>
    </div>
    <p class="section-intro">
      Nike's price history unfolds across three distinct structural phases: a volatile early decade from 2000–2012 with modest overall gains, a powerful secular bull market from 2013–2021, and a significant multi-year retracement from 2021 onward. The chart below plots monthly closing prices with key inflection points annotated.
    </p>

    <div class="chart-wrap">
      <div class="chart-title">NKE Monthly Closing Price — January 2000 to January 2026 (USD, Adjusted)</div>
      <canvas id="priceChart" height="110"></canvas>
    </div>

    <div class="chart-wrap" style="margin-top:20px">
      <div class="chart-title">Drawdown from Running Peak (%)</div>
      <canvas id="drawdownChart" height="80"></canvas>
    </div>

    <div class="phase-grid">
      <div class="phase-card consolidation">
        <div class="phase-period">2000 – 2002</div>
        <div class="phase-name">Post-Bubble Correction</div>
        <div class="phase-return bear">&minus;21%</div>
        <div class="phase-desc">Broad market correction following dot-com bust; NKE declined from $5.22 to $4.20 by end-2002 with extreme intra-period lows near $2.47.</div>
      </div>
      <div class="phase-card bull">
        <div class="phase-period">2003 – 2007</div>
        <div class="phase-name">First Bull Phase</div>
        <div class="phase-return bull">+180%</div>
        <div class="phase-desc">Strong global consumer spending drove NKE from ~$4.20 to $12.60. Nike's international expansion strategy gained traction.</div>
      </div>
      <div class="phase-card bear">
        <div class="phase-period">2008 – 2009</div>
        <div class="phase-name">Financial Crisis</div>
        <div class="phase-return bear">&minus;18%</div>
        <div class="phase-desc">Global Financial Crisis pulled NKE lower, though the stock held up better than the broader market, reflecting its defensive consumer brand attributes.</div>
      </div>
      <div class="phase-card bull">
        <div class="phase-period">2010 – 2021</div>
        <div class="phase-name">Secular Bull Market</div>
        <div class="phase-return bull">+1,065%</div>
        <div class="phase-desc">The dominant phase. NKE surged from $13.41 to $166.25 as digital commerce, athleisure trends, and global brand expansion supercharged growth.</div>
      </div>
      <div class="phase-card bear">
        <div class="phase-period">2022 – 2025</div>
        <div class="phase-name">Prolonged Retracement</div>
        <div class="phase-return bear">&minus;62%</div>
        <div class="phase-desc">Inventory glut, slowing China growth, margin compression, and DTC strategy missteps drove a multi-year decline from the $166 ATH.</div>
      </div>
      <div class="phase-card consolidation">
        <div class="phase-period">2026 YTD</div>
        <div class="phase-name">Base Formation?</div>
        <div class="phase-return bear">&minus;2.3%</div>
        <div class="phase-desc">Stock stabilizing near $62 as of January 2026. Investors weighing turnaround potential under new leadership against lingering macro headwinds.</div>
      </div>
    </div>

    <div class="insight-box" style="margin-top:24px">
      <h3>Price Trend Insights</h3>
      <ul class="insight-list">
        <li>The 2010–2021 bull run produced a 1,065% gain in 11 years — the single most value-creating period in NKE's listed history.</li>
        <li>The all-time high of $166.25 was set on November 5, 2021, coinciding with peak post-COVID consumer demand and macro liquidity.</li>
        <li>The adjusted all-time low of $2.47 (February 25, 2000) reflects split-adjusted pricing; the stock has increased ~25x from that trough.</li>
        <li>The current price of $61.81 is back to late-2017/early-2018 levels, erasing nearly 8 years of gains from the peak.</li>
      </ul>
    </div>
  </section>

  <!-- VOLATILITY ANALYSIS -->
  <section class="section">
    <div class="section-header">
      <div class="section-number">3</div>
      <h2>Volatility and Risk Assessment</h2>
    </div>
    <p class="section-intro">
      Over the full 26-year period, NKE exhibited annualized volatility of 31.2%. Volatility was highest during the 2000–2002 and 2008–2009 crises, and surged again during the post-2021 multi-year retracement. The charts below show rolling 30-day realized volatility and monthly High-Low price ranges.
    </p>

    <div class="two-col">
      <div class="chart-wrap">
        <div class="chart-title">Rolling 30-Day Annualized Volatility (%)</div>
        <canvas id="volChart" height="160"></canvas>
      </div>
      <div class="chart-wrap">
        <div class="chart-title">Monthly High-Low Range (USD)</div>
        <canvas id="rangeChart" height="160"></canvas>
      </div>
    </div>

    <div class="insight-box">
      <h3>Risk Assessment Insights</h3>
      <ul class="insight-list">
        <li>The maximum single-security drawdown of -68.5% (Nov 2021 – Apr 2025) is the largest in NKE's recorded history, exceeding even the 2008 GFC drawdown.</li>
        <li>The 2000–2002 period saw the highest relative volatility due to early-2000 price lows near $2.47, creating enormous percentage swings on a small base.</li>
        <li>The 2013–2019 bull period was remarkably low-volatility for equities, with NKE compounding steadily with minimal drawdowns.</li>
        <li>High-Low monthly ranges widened significantly post-2021, reflecting elevated uncertainty and institutional repositioning.</li>
      </ul>
    </div>
  </section>

  <!-- VOLUME ANALYSIS -->
  <section class="section">
    <div class="section-header">
      <div class="section-number">4</div>
      <h2>Trading Volume Patterns</h2>
    </div>
    <p class="section-intro">
      Average daily trading volume peaked at 17.3M shares/day during 2008 and has trended modestly lower since, reflecting the broader shift to ETF-based investing and reduced single-stock activity. Notable volume spikes correlate directly with major earnings misses, guidance cuts, and macro events.
    </p>

    <div class="chart-wrap">
      <div class="chart-title">Monthly Average Daily Volume (Millions of Shares) vs. Price</div>
      <canvas id="volumeChart" height="110"></canvas>
    </div>

    <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:20px">
      <div class="kpi-card">
        <div class="kpi-label">2000–2009 Avg Daily Vol</div>
        <div class="kpi-value" style="font-size:1.4rem;color:var(--text)">12.96M</div>
        <div class="kpi-sub">Highest era — GFC-driven spikes</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">2010–2019 Avg Daily Vol</div>
        <div class="kpi-value" style="font-size:1.4rem;color:var(--text)">9.00M</div>
        <div class="kpi-sub">Declining as stock priced higher</div>
